INSERT INTO p VALUES ('a');
CREATE TABLE c (id int, k text REFERENCES p ON UPDATE CASCADE, flag int, pad text, CHECK (flag = 0 OR k = 'a'));
CREATE INDEX c_i ON c (pad, k);
